import{_ as e,o as a,c as o,a6 as i}from"./chunks/framework.BHBQfcoO.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md"}'),n={name:"getting-started/installation.md"};function r(s,t,l,d,c,h){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Home Assistant 2026.10 or newer.</strong> LCARdS relies on 2026.10&#39;s dashboard visibility handling and validation library; on older versions the integration logs an error and does not load.</li></ul><p>Something not working after installing? See <a href="./getting-help.html">Getting Help</a>; the LCARdS panel&#39;s Welcome tab has a built-in health check.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><ol><li>Install from HACS</li><li>Add LCARdS integration to HA</li><li>Initialize and Configure LCARdS from LCARdS Config Panel</li></ol><div class="tip custom-block"><p class="custom-block-title">HA-LCARS Theme Integration</p><p>LCARdS supports and integrates well with <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer"><strong>HA-LCARS themes</strong></a>. Use these two together for the best experience.</p><p>Once HA-LCARS is installed, append the <strong>LCARdS theme profiles</strong> to your <code>themes.yaml</code> to map the full LCARdS colour palette to the HA-LCARS chrome and HA core colour tokens in one step; see <a href="./../configuration/ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a>.</p></div><h2 id="_1-install-via-hacs" tabindex="-1">1. Install via HACS <a class="header-anchor" href="#_1-install-via-hacs" aria-label="Permalink to &quot;1. Install via HACS&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=snootched&amp;repository=LCARdS&amp;category=integration" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Open in HACS"></a></p><ol><li>Open <strong>HACS</strong> in Home Assistant</li><li>Go to <strong>Integrations</strong> and search for <strong>LCARdS</strong></li><li>Click <strong>Download</strong> and confirm</li><li><strong>Restart Home Assistant</strong></li><li>Go to <strong>Settings → Integrations → Add Integration</strong> and search for <strong>LCARdS</strong></li><li>Click through the setup (configuration options below)</li></ol><p>LCARdS is now active. It automatically:</p><ul><li>Module <code>lcards.js</code> is available on page load and across every Home Assistant page</li><li>Registers the <strong>LCARdS Config</strong> sidebar panel</li></ul><h3 id="manual-installation" tabindex="-1">Manual Installation <a class="header-anchor" href="#manual-installation" aria-label="Permalink to &quot;Manual Installation&quot;">​</a></h3><details><summary>Manual installation (unmanaged updates)</summary><ol><li>Download <code>lcards.zip</code> from the <a href="https://github.com/snootched/lcards/releases/latest" target="_blank" rel="noreferrer">latest GitHub release</a></li><li>Extract the contents into <code>config/custom_components/lcards/</code> (the directory should contain <code>manifest.json</code> and <code>__init__.py</code> directly, not a nested <code>lcards/lcards/</code> folder)</li><li><strong>Restart Home Assistant</strong></li><li>Go to <strong>Settings → Integrations → Add Integration → LCARdS</strong></li></ol></details><div class="info custom-block"><p class="custom-block-title"><code>lovelace-layout-card</code> compatibility</p><p>LCARdS works well with <a href="https://github.com/thomasloven/lovelace-layout-card" target="_blank" rel="noreferrer"><code>lovelace-layout-card</code></a> There are some quirks to be aware of when using <code>grid-layout</code> - we have a patched version that fixes the margin issue and will remain available until fixed upstream.</p><p>Please see <a href="./../cards/common.html#sizing-inside-custom-layout-card">Sizing Inside Custom Layout</a> for details.</p></div><h2 id="_2-configuration-integration" tabindex="-1">2. Configuration (Integration) <a class="header-anchor" href="#_2-configuration-integration" aria-label="Permalink to &quot;2. Configuration (Integration)&quot;">​</a></h2><p>After installation, LCARdS integration options can be configured from the integration configuration:</p><p><strong>Settings → Integrations → LCARdS → Configure</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Show sidebar panel</td><td>On</td><td>Display the LCARdS Config entry in the Home Assistant sidebar. Disable if you prefer a cleaner sidebar; the integration stays active and all cards continue to work.</td></tr><tr><td>Sidebar Title</td><td>LCARdS Config</td><td>Customizable title for the sidebar entry.</td></tr><tr><td>Sidebar Icon</td><td><code>mdi:space-invaders</code></td><td>Customizable icon for the sidebar entry.</td></tr><tr><td>Log Level</td><td><code>warn</code></td><td>Default logging level for all cards. <code>debug</code>, <code>trace</code> are excessively versbose - only used for deep troubleshooting.</td></tr><tr><td>Enable Preview Features</td><td><code>false</code></td><td>Unlocks features that are still under active development. These may change during development - Please provide your feedback, discuss or get help on GitHub Issues and Discussions.</td></tr></tbody></table><p>Changes take effect immediately; no restart required.</p><h2 id="_3-lcards-configuarion-config-panel" tabindex="-1">3. LCARdS Configuarion - Config Panel <a class="header-anchor" href="#_3-lcards-configuarion-config-panel" aria-label="Permalink to &quot;3. LCARdS Configuarion - Config Panel&quot;">​</a></h2><p>The <a href="./../configuration/"><strong>LCARdS Config Panel</strong></a> is registered automatically by the integration. Access it via the <strong>LCARdS Config</strong> entry in the Home Assistant sidebar.</p><p>Follow the setup flow in the Config Panel, and explore other options like:</p><ul><li><strong>Create all required helpers</strong> in one click (alert mode, sounds, sizing)</li><li>Customise Alert Mode colour palettes</li><li>Configure sound schemes and overrides</li></ul><p>After setup, if you don&#39;t want it visible all the time, toggle <strong>Show sidebar panel</strong> off in the integration options; it can be re-enabled at any time.</p><p>See <a href="./../configuration/">Configuration overview</a> for full details.</p>',26)])])}const p=e(n,[["render",r]]);export{u as __pageData,p as default};
